// Algorithms → the knowledge-graph workspace, AS GRAPH SOURCE (#4219, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui
// design system + the store via appModules, the knowledge/viz surface via the algorithms graph-platform,
// and the sibling views as @/components/* graph records). Behaviour runs here.
// The Algorithms knowledge-graph page (#2761, epic #2760 · #2863 · #2899) — rendered on the shared
// GraphCanvas + useGraphViewport (the Glance/Teams/Designs stack). A concept IS its implementation
// (#2958): the graph's nodes are the active kit's impls (primitives + algorithms), wired by `composes`
// (down to the primitive base). The inspector shows the selected impl's code + what it builds on / is
// used by. The seed is authored in @data/knowledge and hydrated live from the librarian's writable
// store (#2856).
//
// THE LANGUAGE IS A TAB (`technology-tabs-for-components-and-algorithms`). It used to be the top level
// of the left rail — a folder per language, its impls the rows (#2899) — so the rail carried two
// different kinds of thing at once: which language you are in, and where you are inside it. The
// language moves up into the page tabs; the rail keeps the part that is genuinely navigation within a
// language, its folder tree.
//
// THE TAB IS A LENS, NOT A PARTITION (`the-tab-is-a-lens-not-a-partition`), and that distinction is
// load-bearing rather than decorative. Technology is a CURATION scope — it says who may WRITE a record
// (`studioScopeDirective` splits the librarian per language) — and says nothing about what may
// REFERENCE one. The cross-graph URN grammar makes that concrete: `@bsc/algorithms/fibonacci` is
// kit-less, so a React component resolves a TypeScript implementation across both pillar AND
// technology. A tab bar that rendered languages as disjoint worlds would assert in the chrome exactly
// the silo epic #3114 removed from the model.
//
// What that obliges here: selecting a tab changes FOCUS, never which edges exist. `kitGraph` filters
// `composes` to targets within the same language, so an edge that ever crossed one would be dropped
// silently — no error, just a link that is not drawn. There are none today (measured: 578 within-tech,
// 0 cross-tech), so this is a guard rather than a fix, and `algorithmsLens.test.ts` is what fails the
// day one appears.
import { useEffect, useMemo, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import { Button } from "@/shared/ui/controls/Button";
import { GraphCanvas, ZoomControls } from "@/shared/ui/layouts/GraphCanvas";
import { GraphLegend } from "@/shared/ui/layouts/GraphLegend";
import { useGraphViewport } from "@/shared/ui/layouts/useGraphViewport";
import { useDragResize } from "@/shared/hooks/useDragResize";
import { useDockEntrance } from "@/shared/hooks/useDockEntrance";
import { useCrumbEntity } from "@/shared/hooks/useCrumbEntity";
import { usePageTabs } from "@/shared/hooks/usePageTabs";
import { Screen } from "@/shared/ui/layouts/Screen";
import { AlgorithmsKitGraph } from "@/features/algorithms/AlgorithmsKitGraph";
import { AlgorithmsInspector } from "@/features/algorithms/AlgorithmsInspector";
import { AlgorithmsRail } from "@/features/algorithms/AlgorithmsRail";
import { LibrarianTerminal } from "@/features/algorithms/LibrarianTerminal";
import { VizStage } from "@/features/algorithms/viz/VizPanel";
import { useVizForImpl } from "@/features/algorithms/viz/useVizForImpl";
import {
  TECHS, TECH_META, NODE_W, NODE_H, layoutKitGraph, kitGraph, kitTechs, implById,
  KIT_REL_META, KIT_REL_ORDER, type Tech,
} from "@/features/algorithms/lib/knowledge";
import { useKnowledgeGraph } from "@/features/algorithms/useKnowledgeGraph";

export function AlgorithmsWorkspace() {
  // Live graph (#2856): the seed for an instant first paint, hydrated + kept fresh from the librarian's
  // writable store (`bsc graph dump`) so their curation shows.
  const graph = useKnowledgeGraph();

  // One tab per language the graph HOLDS — `kitTechs` intersects the canonical order with what is
  // present, so a language with no implementations yet shows no empty tab, and a language the seed
  // grows appears without a code change here.
  const techTabs = useMemo(
    () => kitTechs(graph).map((t) => ({
      id: t,
      label: TECH_META[t]?.label ?? t,
      hint: `${TECH_META[t]?.label ?? t} implementations`,
    })),
    [graph],
  );
  // UNCONTROLLED (`navigation-vocabulary-follows-the-new-page-structure`): the active tab lives in the
  // store at `activePageTab["algorithms"]`, and the active language is READ from it rather than held
  // beside it in local state.
  //
  // That is what makes `bsc navigate page rust` work. A controlled tab keeps its selection in the
  // component, where `navigate` cannot reach — so the verb would have written the store, the page would
  // have ignored it, and the ack would have reported a language the user was not looking at. It also
  // means the tab survives a restart, which local state did not.
  //
  // A persisted id that no longer names a real language heals to the first tab (usePageTabs does this),
  // so a language dropped from the seed cannot strand anyone on a dead tab.
  //
  // Tear-off is deliberately NOT wired (`onTearOff` omitted). `studioDetached` reads
  // `detachedSections[pageKey]` looking for a studio's `sectionId`, which is still "algorithms" and
  // not a language — so offering tear-off here would write a key nothing matches and hand a user a
  // detached window the librarian dock does not follow.
  const { tabs, activeId, select, reorder } = usePageTabs("algorithms", techTabs);
  const activeTech = (kitTechs(graph).includes(activeId as Tech) ? activeId : kitTechs(graph)[0] ?? TECHS[0]) as Tech;
  /** Switch language: the tab IS the selection, so this goes through `select`. */
  const setActiveTech = (t: Tech) => { select(t); setSelectedImpl(null); };
  // The selected implementation (a node in the active kit's graph), shown in the inspector.
  const [selectedImpl, setSelectedImpl] = useState<string | null>(null);
  const focusedImpl = selectedImpl ? implById(graph, selectedImpl) ?? null : null;

  // The visualization take-over (#3205): when expanded, the focused impl's animation covers the graph
  // canvas (rail + inspector stay), mirroring the Components theme try-on. Track WHICH impl is expanded
  // (not a bare boolean) so selecting a different node auto-returns to the graph — `vizExpanded` is the
  // derived "the current selection is the expanded one", no reset effect needed. Its registered viz, if any.
  const [expandedImplId, setExpandedImplId] = useState<string | null>(null);
  const focusedViz = useVizForImpl(focusedImpl);
  const vizExpanded = expandedImplId != null && expandedImplId === selectedImpl;

  // The active language's OWN graph (impls + composes edges, down to the primitive base) + its layout.
  const kit = useMemo(() => kitGraph(graph, activeTech), [graph, activeTech]);
  // Name the active language in the titlebar crumb (#3041).
  useCrumbEntity("algorithms", TECH_META[activeTech]?.label ?? activeTech);
  const kitLayout = useMemo(() => layoutKitGraph(kit), [kit]);

  // The on-graph legend (#2909) — the relationship types ACTUALLY present in this kit's edges, keyed off
  // the same KIT_REL_META the canvas draws with, so it reads relevant to the language on screen.
  const legend = useMemo(() => {
    const present = new Set(kit.edges.map((e) => e.rel));
    const edges = KIT_REL_ORDER.filter((r) => present.has(r)).map((r) => ({ label: KIT_REL_META[r].label, dashed: KIT_REL_META[r].dashed }));
    return <GraphLegend sections={[{ label: "Relationships", edges }]} />;
  }, [kit.edges]);

  const vp = useGraphViewport(kitLayout.world, { contentBounds: () => kitLayout.bounds });
  // Frame the content on mount AND whenever the active language switches (each kit has its own world).
  useEffect(() => { vp.fit(); }, [activeTech]); // eslint-disable-line react-hooks/exhaustive-deps

  // Select an impl: switch to ITS language if needed, select it, and — when it is already the active
  // kit — pan its node to center.
  //
  // The cross-language branch is NOT dead code now that the rail shows one language. The INSPECTOR
  // links to what an impl builds on and what uses it, and the day a `composes` edge crosses a
  // language that link lands here — so following it must move the tab rather than select an id the
  // visible graph does not contain, which would leave the inspector describing a node nobody can see.
  const selectImplFromRail = (id: string) => {
    const im = implById(graph, id);
    if (!im) return;
    setSelectedImpl(id);
    if (im.tech !== activeTech) {
      setActiveTech(im.tech); // the [activeTech] fit effect frames the new kit
      return;
    }
    const p = kitLayout.pos.get(id);
    if (p) vp.centerOn(p.x + NODE_W / 2, p.y + NODE_H / 2);
  };

  // The always-on librarian session's dock height (#2787) — a row-resize handle above it; `invert`
  // because the terminal sits AFTER the handle, so dragging up grows it. Mirrors the Teams dock (#2759).
  const term = useDragResize({ initial: 340, min: 140, max: 560, axis: "y", invert: true });
  useDockEntrance(term.setSize, 340); // grow the dock up into place on mount (#2905)

  // Header: the active language + its graph counts (the rail folders are the language switcher now), then
  // the graph nav (zoom/fit).
  const toolbar = (
    <>
      <Eyebrow size={10}>Algorithms</Eyebrow>
      {/* The active language is on the TAB now, so the toolbar reports only what the tab cannot: the
          size of the graph on screen. Repeating the language here would be two labels for one fact. */}
      <Text mono size="xxs" tone="dim">
        {kit.nodes.length} impls · {kit.edges.length} links
      </Text>
      <Box style={{ flex: 1 }} />
      <ZoomControls vp={vp} />
      <Button size="sm" variant="ghost" onClick={vp.fit}>Fit</Button>
    </>
  );

  return (
    <Screen
      className="algorithms-workspace"
      tabs={tabs}
      active={activeId}
      onSelect={select}
      onReorder={reorder}
    >
    <GraphCanvas
      profileId="algorithms"
      vp={vp}
      world={kitLayout.world}
      grid
      toolbar={toolbar}
      // In-canvas visualization take-over (#3205): when the user expands a focused impl's inline preview,
      // its animation covers the graph here (like the Designs theme try-on), with a ← Back to graph bar.
      // Otherwise the on-graph relationship legend.
      overlays={vizExpanded && focusedViz && focusedImpl
        ? <VizStage viz={focusedViz} implName={focusedImpl.name} onBack={() => setExpandedImplId(null)} />
        : legend}
      rail={<AlgorithmsRail graph={graph} activeTech={activeTech} selectedImpl={selectedImpl} onSelectImpl={selectImplFromRail} />}
      railResizable
      railWidth={230}
      inspector={<AlgorithmsInspector graph={graph} focusedImpl={focusedImpl} onSelectImpl={setSelectedImpl} onExpandViz={() => setExpandedImplId(selectedImpl)} />}
      inspectorResizable
      // Match the Components (Designs) inspector width and go a touch bigger (#3203), so the two
      // libraries read consistently and the always-inline visualization preview (#3199) has room.
      inspectorWidth={460}
      inspectorMin={300}
      inspectorMax={680}
      onBackgroundClick={() => setSelectedImpl(null)}
      // The always-on knowledge-librarian session (#2787), docked below the graph; the caller owns its
      // height + a `.resize-y` handle (GraphCanvas gives it a flex:none slot), mirroring Teams (#2759).
      dock={
        <Box style={{ display: "flex", flexDirection: "column", minHeight: 0 }}>
          <Box className="resize-y" {...term.handleProps} title="Drag to resize" />
          <LibrarianTerminal height={term.size} tech={activeTech} />
        </Box>
      }
    >
      <AlgorithmsKitGraph kit={kit} layout={kitLayout} selected={selectedImpl} onSelect={setSelectedImpl} />
    </GraphCanvas>
    </Screen>
  );
}
